    for (let i = 0; i < nums.length && j < got.length; i++) if (nums[i] === got[j]) j++;
    if (j !== got.length) return false;
    const sum = a => a.reduce((s, x) => s + x, 0);
    return sum(got) === sum(expected);
  }

