function heaviestK(nums: number[], k: number): number[] {
  const a = nums.slice();
  while (a.length > k) {
    let m = 0;
    for (let i = 1; i < a.length; i++) if (a[i] < a[m]) m = i;
    a.splice(m, 1);
  }
  return a;
}

