function heaviestK(nums: number[], k: number): number[] {
  const h: number[] = []; // min-heap of indices, by nums value
  const less = (a: number, b: number) => nums[h[a]] < nums[h[b]];
  const swap = (a: number, b: number) => { [h[a], h[b]] = [h[b], h[a]]; };
  const push = (x: number) => {
    h.push(x);
    for (let i = h.length - 1; i > 0 && less(i, (i - 1) >> 1); i = (i - 1) >> 1) swap(i, (i - 1) >> 1);
  };
  const pop = () => {
    const last = h.pop()!;
    if (h.length === 0) return;
    h[0] = last;
    for (let i = 0; ; ) {
      const l = 2 * i + 1, r = l + 1;
      let m = i;
      if (l < h.length && less(l, m)) m = l;
      if (r < h.length && less(r, m)) m = r;
      if (m === i) break;
      swap(i, m);
      i = m;
    }
  };
  for (let i = 0; i < nums.length; i++) {
    push(i);
    if (h.length > k) pop();
  }
  return h.slice().sort((a, b) => a - b).map(i => nums[i]);
}

